"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { AlertCircle, Loader2, Users, Utensils, CheckCircle, XCircle } from "lucide-react";
import Layout from "../Layout";

export default function ChefInternMealList() {
  const [interns, setInterns] = useState([]);
  const [meals, setMeals] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [isConfirmed, setIsConfirmed] = useState(false);

  useEffect(() => {
    fetchData();
    checkConfirmationStatus();
  }, []);

  const fetchData = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");

    try {
      const [internsRes, mealsRes] = await Promise.all([
        axios.get(`${process.env.REACT_APP_API_URL}/api/interns`, { headers: { Authorization: `Bearer ${token}`, Role: "Chef" } }),
        axios.get(`${process.env.REACT_APP_API_URL}/api/meals/next-day`, { headers: { Authorization: `Bearer ${token}`, Role: "Chef" } }),
      ]);
      setInterns(internsRes.data.data || []);
      setMeals(mealsRes.data || []);
    } catch (err) {
      setError("Erreur lors de la récupération des données : " + (err.response?.data?.message || err.message));
    } finally {
      setIsLoading(false);
    }
  };

  const checkConfirmationStatus = () => {
    const confirmedDate = localStorage.getItem("chefConfirmationDate");
    if (confirmedDate) {
      const today = new Date().toDateString();
      if (new Date(confirmedDate).toDateString() === today) {
        setIsConfirmed(true);
      } else {
        localStorage.removeItem("chefConfirmationDate");
        setIsConfirmed(false);
      }
    }
  };

  const handleConfirm = async () => {
    if (window.confirm("Êtes-vous sûr de vouloir confirmer les repas de demain ? Cela mettra à jour la consommation des stagiaires.")) {
      setError("");
      const token = localStorage.getItem("token");
      try {
        await axios.post(
          `${process.env.REACT_APP_API_URL}/api/meals/confirm-tomorrow`,
          {},
          { headers: { Authorization: `Bearer ${token}`, Role: "Chef" } }
        );
        setIsConfirmed(true);
        localStorage.setItem("chefConfirmationDate", new Date().toISOString());
      } catch (err) {
        setError("Erreur lors de la confirmation : " + (err.response?.data?.message || err.message));
      }
    }
  };

  const handleUnconfirm = async () => {
    if (window.confirm("Êtes-vous sûr de vouloir déconfirmer les repas de demain ? Cela annulera les mises à jour de consommation.")) {
      setError("");
      const token = localStorage.getItem("token");
      try {
        await axios.post(
          `${process.env.REACT_APP_API_URL}/api/meals/unconfirm-tomorrow`,
          {},
          { headers: { Authorization: `Bearer ${token}`, Role: "Chef" } }
        );
        setIsConfirmed(false);
        localStorage.removeItem("chefConfirmationDate");
        await fetchData(); // Refresh data to reflect updated consommation
      } catch (err) {
        setError("Erreur lors de la déconfirmation : " + (err.response?.data?.message || err.message));
      }
    }
  };

  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  tomorrow.setHours(0, 0, 0, 0);

  const benefitingInterns = interns.filter((intern) => {
    const optOutForTomorrow = intern.mealOptOuts.find((opt) => {
      const optDate = new Date(opt.date);
      return optDate.toDateString() === tomorrow.toDateString();
    });
    return !optOutForTomorrow || optOutForTomorrow.mealTypes.length < meals.length;
  });

  const totalInterns = benefitingInterns.length;
  const breakfastCount = benefitingInterns.filter((intern) => {
    const optOutForTomorrow = intern.mealOptOuts.find((opt) => {
      const optDate = new Date(opt.date);
      return optDate.toDateString() === tomorrow.toDateString();
    });
    return !optOutForTomorrow || !optOutForTomorrow.mealTypes.includes("Breakfast");
  }).length;
  const lunchCount = benefitingInterns.filter((intern) => {
    const optOutForTomorrow = intern.mealOptOuts.find((opt) => {
      const optDate = new Date(opt.date);
      return optDate.toDateString() === tomorrow.toDateString();
    });
    return !optOutForTomorrow || !optOutForTomorrow.mealTypes.includes("Lunch");
  }).length;
  const dinnerCount = benefitingInterns.filter((intern) => {
    const optOutForTomorrow = intern.mealOptOuts.find((opt) => {
      const optDate = new Date(opt.date);
      return optDate.toDateString() === tomorrow.toDateString();
    });
    return !optOutForTomorrow || !optOutForTomorrow.mealTypes.includes("Dinner");
  }).length;

  return (
    <Layout>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6 flex justify-between items-center">
            <div>
              <h2 className="text-2xl font-bold tracking-tight">Stagiaires Bénéficiant des Repas de Demain</h2>
              <p className="text-white/80 mt-1 text-sm">Liste et analyse des stagiaires inscrits pour les repas du lendemain</p>
            </div>
            <div className="flex gap-2">
              <button
                onClick={handleConfirm}
                disabled={isConfirmed}
                className={`px-4 py-2 rounded-md text-white font-medium flex items-center gap-2 ${
                  isConfirmed ? "bg-gray-400 cursor-not-allowed" : "bg-[#00717F] hover:bg-[#00717F]"
                } transition-colors`}
              >
                <CheckCircle className="h-5 w-5" />
                {isConfirmed ? "Confirmé" : "Confirmer"}
              </button>
              {isConfirmed && (
                <button
                  onClick={handleUnconfirm}
                  className="px-4 py-2 rounded-md text-white font-medium flex items-center gap-2 bg-red-600 hover:bg-red-700 transition-colors"
                >
                  <XCircle className="h-5 w-5" />
                  Déconfirmer
                </button>
              )}
            </div>
          </div>

          <div className="p-6 bg-[#F5F6FA] border-b border-[#C8A45D/30]">
            <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
              <div className="bg-white p-4 rounded-lg shadow-sm flex items-center gap-3">
                <Users className="h-8 w-8 text-[#00717F]" />
                <div>
                  <p className="text-sm font-medium text-#333333">Total Stagiaires</p>
                  <p className="text-2xl font-bold text-[#00717F]">{totalInterns}</p>
                </div>
              </div>
              <div className="bg-white p-4 rounded-lg shadow-sm flex items-center gap-3">
                <Utensils className="h-8 w-8 text-[#00717F]" />
                <div>
                  <p className="text-sm font-medium text-#333333">Petit-déjeuner</p>
                  <p className="text-2xl font-bold text-[#00717F]">{breakfastCount}</p>
                </div>
              </div>
              <div className="bg-white p-4 rounded-lg shadow-sm flex items-center gap-3">
                <Utensils className="h-8 w-8 text-[#00717F]" />
                <div>
                  <p className="text-sm font-medium text-#333333">Déjeuner</p>
                  <p className="text-2xl font-bold text-[#00717F]">{lunchCount}</p>
                </div>
              </div>
              <div className="bg-white p-4 rounded-lg shadow-sm flex items-center gap-3">
                <Utensils className="h-8 w-8 text-[#00717F]" />
                <div>
                  <p className="text-sm font-medium text-#333333">Dîner</p>
                  <p className="text-2xl font-bold text-[#00717F]">{dinnerCount}</p>
                </div>
              </div>
            </div>
          </div>

          {error && (
            <div className="p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3">
              <AlertCircle className="h-5 w-5 text-red-500" />
              <p className="text-red-700 text-sm">{error}</p>
            </div>
          )}

          <div className="p-6">
            {isLoading ? (
              <div className="flex justify-center items-center h-64">
                <div className="flex flex-col items-center gap-2">
                  <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                  <p className="text-[#00717F] text-sm font-medium">Chargement des données...</p>
                </div>
              </div>
            ) : benefitingInterns.length === 0 ? (
              <p className="text-gray-500 text-center">Aucun stagiaire ne bénéficie des repas de demain.</p>
            ) : (
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-[#C8A45D/30]">
                  <thead>
                    <tr className="bg-[#F5F6FA] text-[#00717F]">
                      <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider rounded-tl-lg">Nom Complet</th>
                      <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Genre</th>
                      <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Emplacement</th>
                      <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider rounded-tr-lg">Repas Préférés</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                    {benefitingInterns.map((intern) => {
                      const optOutForTomorrow = intern.mealOptOuts.find((opt) => {
                        const optDate = new Date(opt.date);
                        return optDate.toDateString() === tomorrow.toDateString();
                      });
                      const optedOutMeals = optOutForTomorrow ? optOutForTomorrow.mealTypes : [];
                      const preferredMeals = meals
                        .filter((meal) => !optedOutMeals.includes(meal.type))
                        .map((meal) => (meal.type === "Breakfast" ? "Petit-déjeuner" : meal.type === "Lunch" ? "Déjeuner" : "Dîner"));

                      return (
                        <tr key={intern._id} className="hover:bg-[#F5F6FA]/30 transition-colors duration-150">
                          <td className="py-4 px-4 text-sm font-medium text-gray-900">{`${intern.First_Name} ${intern.Last_Name}`}</td>
                          <td className="py-4 px-4 text-sm text-#333333">{intern.Gender === "Male" ? "Garçon" : "Fille"}</td>
                          <td className="py-4 px-4 text-sm text-#333333">{intern.emplacement}</td>
                          <td className="py-4 px-4 text-sm text-#333333">
                            {preferredMeals.length > 0 ? preferredMeals.join(", ") : "Aucun"}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>
    </Layout>
  );
}
